// Minimax with memoization on the array range - Stone Game family
function stoneGame(piles) {
  const n = piles.length;
  const memo = new Map();

  function best(i, j) {
    if (i > j) return 0;
    const key = i * n + j;
    if (memo.has(key)) return memo.get(key);

    // Whoever's turn it is picks the end that maximizes (this move's gain - opponent's best response)
    const takeLeft = piles[i] - best(i + 1, j);
    const takeRight = piles[j] - best(i, j - 1);
    const result = Math.max(takeLeft, takeRight);

    memo.set(key, result);
    return result;
  }

  return best(0, n - 1) > 0;   // first player wins if their net score advantage is positive
}

// Nim / Sprague-Grundy: compute Grundy number for a single-pile subtraction game
function grundy(pile, moves, memo = new Map()) {
  if (memo.has(pile)) return memo.get(pile);
  const reachable = new Set();
  for (const m of moves) {
    if (m <= pile) reachable.add(grundy(pile - m, moves, memo));
  }
  let mex = 0;
  while (reachable.has(mex)) mex++;   // smallest non-negative integer not reachable
  memo.set(pile, mex);
  return mex;
}

// Combine independent piles/sub-games: first player wins iff XOR of Grundy numbers != 0
function firstPlayerWins(piles, moves) {
  return piles.reduce((xor, p) => xor ^ grundy(p, moves), 0) !== 0;
}
